let masterIp = global.get('master_ip') || flow.get('master_ip') || '192.168.23.100';
let msgs = [];
for (let i = 1; i <= 4; i++) {
    let alias = `master1port${i}`;
    msgs.push({ 
        url: `http://${masterIp}/iolink/v1/devices/${alias}/processdata/value?format=byteArray`,
        portId: i,
        reqType: 'dev_pd'
    });
}
return [msgs];

function unpackProcessData(bytes, iodd) {
    let results = {};
    if (!Array.isArray(bytes) || bytes.length === 0) return results;

    if (iodd && iodd.valid && iodd.processDataInItems && iodd.processDataInItems.length > 0) {
        let totalBits = 0n;
        bytes.forEach(b => { totalBits = (totalBits << 8n) | BigInt(b); });

        iodd.processDataInItems.forEach(item => {
            let bitLen = BigInt(item.bitLen || 16);
            let bitOffset = BigInt(item.bitOffset || 0);
            let mask = (1n << bitLen) - 1n;
            let rawChunk = Number((totalBits >> bitOffset) & mask);
            let dt = (item.dataType || 'uinteger').toLowerCase();
            let isSigned = dt.includes('int') && !dt.includes('uint') && !dt.includes('bool') && bitLen > 1n;

            if (isSigned && bitLen > 1n) {
                let signLimit = 1n << (bitLen - 1n);
                if (BigInt(rawChunk) >= signLimit) {
                    rawChunk = Number(BigInt(rawChunk) - (1n << bitLen));
                }
            }

            let scale = item.scale || { gradient: 1, offset: 0 };
            let nameLower = (item.name || '').toLowerCase();
            let grad = scale.gradient || 1;
            let uCode = String(scale.unitCode || '');

            if (grad === 1) {
                if (nameLower.includes('temp') || nameLower.includes('hőmérséklet')) grad = 0.1;
                else if (nameLower.includes('voltage') || nameLower.includes('feszültség') || nameLower.includes('supply')) {
                    if (rawChunk > 1000) grad = 0.001;
                    else if (rawChunk > 100) grad = 0.1;
                }
            }

            let val = (rawChunk * grad) + (scale.offset || 0);
            let decimals = grad < 1 ? Math.abs(Math.round(Math.log10(grad))) : 0;
            let unit = item.unit || '';

            if (!unit) {
                if (uCode === '1240' || nameLower.includes('voltage') || nameLower.includes('feszültség') || nameLower.includes('supply')) unit = 'V';
                else if (uCode === '1001' || nameLower.includes('temp') || nameLower.includes('hőmérséklet')) unit = '°C';
                else if (uCode === '1133' || nameLower.includes('bar') || nameLower.includes('nyomás')) unit = 'bar';
                else if (uCode === '1013' || nameLower.includes('dist') || nameLower.includes('távolság')) unit = 'mm';
                else if (nameLower.includes('pwm') || nameLower.includes('hum') || nameLower.includes('duty')) unit = '%';
                else if (nameLower.includes('current') || nameLower.includes('áram')) unit = 'mA';
            }

            results[item.name] = {
                val: Number(val.toFixed(decimals)),
                unit: unit
            };
        });
    } else {
        // FAT/SAT #5 & #15: Format raw HEX Process Data when no IODD is loaded
        let hexStr = '0x' + bytes.map(b => b.toString(16).padStart(2, '0').toUpperCase()).join('');
        let rawNum = 0;
        if (bytes.length === 1) rawNum = bytes[0];
        else if (bytes.length === 2) rawNum = (bytes[0] << 8) | bytes[1];
        else bytes.forEach(b => { rawNum = (rawNum << 8) | b; });

        results['Raw HEX PD'] = { val: hexStr, unit: '' };
        if (bytes.length <= 2) {
            results['Dec Value'] = { val: rawNum, unit: '' };
        }
    }
    return results;
}

let state = global.get('nass_core_state') || flow.get('nass_core_state') || {
    info: { product: '---', vendor: '---', sn: '---', fwhw: '---', mac: '---', order: '---' },
    net: { ip: '---', mask: '---', gw: '---', eth0: '---', eth1: '---' },
    leds: { pwr: false, stat: false, diag: false, lnk: false, flt: false },
    ports: [1,2,3,4].map(i => ({ 
        id: i, mode: 'IOLINK_AUTOSTART', status: 'ISMERETLEN', 
        vendor: '---', device: '---', deviceId: null, sn: '---', pdValues: {}, 
        ledMode: false, ledCom: false, doState: false, diState: false 
    }))
};

let now = Date.now();
let lastSuccess = flow.get('nass_last_success') || now;
let d = msg.payload ? (msg.payload.data || msg.payload) : null;
let isDataValid = (d && typeof d === 'object' && Object.keys(d).length > 0 && !msg.error);

if (isDataValid) {
    flow.set('nass_last_success', now);
    flow.set('nass_comm_lost', false);
} else {
    let elapsed = now - lastSuccess;
    if (elapsed > 4000) {
        state.leds = { pwr: false, stat: false, diag: false, lnk: false, flt: false };
        state.net.eth0 = 'LINK_DOWN (COMM_LOST)';
        state.net.eth1 = 'LINK_DOWN (COMM_LOST)';
        state.ports.forEach(p => {
            p.status = 'COMM_LOST'; p.ledMode = false; p.ledCom = false; p.pdValues = {};
        });
        flow.set('nass_core_state', state);
        global.set('nass_core_state', state);
        return { topic: 'state_update', payload: state };
    } else { return null; }
}

let url = msg.responseUrl || msg.url || '';
let urlLower = url.toLowerCase();

if (urlLower.endsWith('/gateway/identification')) {
    state.info.product = d.productName || state.info.product;
    state.info.vendor = d.vendorName || state.info.vendor;
    state.info.sn = d.serialNumber || state.info.sn;
    state.info.fwhw = `${d.firmwareRevision || '?'} / ${d.hardwareRevision || '?'}`;
    state.info.mac = d.macAddress || state.info.mac;
} else if (urlLower.endsWith('/masters/1/identification')) {
    state.info.order = d.orderCode || state.info.order;
} else if (urlLower.endsWith('/gateway/configuration')) {
    if (d.ethIpv4 && d.ethIpv4[0]) {
        state.net.ip = `${d.ethIpv4[0].ipAddress} (${d.ethIpv4[0].ipConfiguration})`;
        state.net.mask = d.ethIpv4[0].subnetMask;
        state.net.gw = d.ethIpv4[0].standardGateway;
    }
} else if (urlLower.endsWith('/gateway/ethernetstate')) {
    state.net.eth0 = d.eth0 ? `${d.eth0.linkState} (${d.eth0.linkSpeed})` : 'NO_LINK';
    state.net.eth1 = d.eth1 ? `${d.eth1.linkState} (${d.eth1.linkSpeed})` : 'NO_LINK';
} else if (urlLower.endsWith('/gateway/ledstate')) {
    state.leds.pwr = (d.power === 1 || d.power === true);
    state.leds.stat = (d.status === 1 || d.status === true);
    state.leds.diag = (d.diag === 1 || d.diag === true);
    state.leds.lnk = (d.link === 1 || d.link === true);
    state.leds.flt = (d.fault === 1 || d.fault === true);
    for(let i=1; i<=4; i++) {
        let pad = 'X0' + (i-1);
        state.ports[i-1].ledMode = (d[pad+'mode'] === 1 || d[pad+'mode'] === true);
        state.ports[i-1].ledCom = (d[pad+'com'] === 1 || d[pad+'com'] === true);
    }
} else if (urlLower.endsWith('/masters/1/ports') && Array.isArray(d)) {
    d.forEach(p => {
        let pIdx = p.portNumber - 1;
        if (pIdx >= 0 && pIdx < 4) {
            let st = String(p.statusInfo || '').toUpperCase();
            let pMode = String(p.mode || p.portMode || (p.configuration && p.configuration.mode) || '').toUpperCase();
            let pStat = String(p.portStatus || p.status || '').toUpperCase();
            if (p.deviceId !== undefined) state.ports[pIdx].deviceId = p.deviceId;
            let iodd = global.get('port_iodd_' + p.portNumber);
            if (iodd && iodd.valid) {
                state.ports[pIdx].vendor = iodd.vendorName || state.ports[pIdx].vendor || '---';
                state.ports[pIdx].device = iodd.deviceName || state.ports[pIdx].device || '---';
            } else if (p.vendorId !== undefined && p.deviceId !== undefined) {
                state.ports[pIdx].vendor = `VID: ${p.vendorId}`;
                state.ports[pIdx].device = `DID: ${p.deviceId}`;
            }
            if (st.includes('DIGITAL_OUTPUT') || pMode.includes('DIGITAL_OUTPUT') || pMode === 'DO' || st.includes('DO_') || pStat.includes('DO')) {
                state.ports[pIdx].mode = 'DIGITAL_OUTPUT'; state.ports[pIdx].status = 'DO_AKTÍV'; state.ports[pIdx].device = 'Digitális Kimenet (DO)'; state.ports[pIdx].vendor = '';
            } else if (st.includes('DIGITAL_INPUT') || pMode.includes('DIGITAL_INPUT') || pMode === 'DI' || st.includes('DI_') || pStat.includes('DI')) {
                state.ports[pIdx].mode = 'DIGITAL_INPUT'; state.ports[pIdx].status = 'DI_AKTÍV'; state.ports[pIdx].device = 'Digitális Bemenet (DI)'; state.ports[pIdx].vendor = '';
            } else if (st.includes('DEACTIVATED') || st === 'DEACTIVATED' || pMode.includes('DEACTIVATED') || pMode === 'OFF') {
                state.ports[pIdx].mode = 'DEACTIVATED';
                state.ports[pIdx].status = 'INAKTÍV';
            } else if (st.includes('ONLINE') || st.includes('DEVICE_ONLINE') || pMode.includes('IOLINK') || pStat.includes('ONLINE')) {
                state.ports[pIdx].mode = 'IOLINK_AUTOSTART';
                state.ports[pIdx].status = 'ONLINE';
            } else if (st.includes('LOST')) {
                state.ports[pIdx].status = 'COMM_LOST';
            } else {
                state.ports[pIdx].status = p.statusInfo || st;
            }
            global.set('port_mode_' + p.portNumber, state.ports[pIdx].mode);
        }
    });
} else if (urlLower.includes('/devices/') && urlLower.includes('/identification')) {
    let portMatch = urlLower.match(/port(\d+)/i);
    let portNum = portMatch ? parseInt(portMatch[1], 10) : 0;
    let idx = portNum - 1;
    if (idx >= 0 && idx < 4) {
        let iodd = global.get('port_iodd_' + portNum);
        if (iodd && iodd.valid) {
            state.ports[idx].vendor = iodd.vendorName || state.ports[idx].vendor || '---';
            state.ports[idx].device = iodd.deviceName || state.ports[idx].device || '---';
        } else if (d) {
            let pName = d.productName || d.productId || d.productname || d.product;
            let vName = d.vendorName || d.vendorname || d.vendor;
            if (pName) state.ports[idx].device = pName;
            if (vName) state.ports[idx].vendor = vName.replace(' electronic gmbh', '');
        }
        let sn = d ? (d.serialNumber || d.serialnumber || d.serialNo || d.serial) : null;
        if (sn) state.ports[idx].sn = sn;
    }
} else if (urlLower.includes('/processdata/')) {
    let matchPd = urlLower.match(/port(\d+)/i);
    let pdPort = matchPd ? parseInt(matchPd[1], 10) : 0;
    let pdIdx = pdPort - 1;
    if (pdIdx >= 0 && pdIdx < 4) {
        let cqVal = undefined;
        let getObj = (d.getData) ? d.getData : d;
        if (d.setData && d.setData.cqValue !== undefined) cqVal = d.setData.cqValue;
        else if (d.getData && d.getData.cqValue !== undefined) cqVal = d.getData.cqValue;
        else if (d.cqValue !== undefined) cqVal = d.cqValue;
        let m = state.ports[pdIdx].mode;

        if (m === 'DIGITAL_INPUT') {
            let diState = false;
            if (d.getData && d.getData.iqValue !== undefined) diState = d.getData.iqValue;
            else if (d.getData && d.getData.cqValue !== undefined) diState = d.getData.cqValue;
            state.ports[pdIdx].diState = diState;
            state.ports[pdIdx].pdValues = { 'Digital In': { val: diState ? 'HIGH (24V)' : 'LOW (0V)', unit: '' } };
        } else if (m === 'DIGITAL_OUTPUT') {
            let isHigh = (cqVal === true);
            state.ports[pdIdx].pdValues = { 'Digital Out': { val: isHigh ? 'HIGH (24V)' : 'LOW (0V)', unit: '' } };
            state.ports[pdIdx].doState = isHigh;
        } else {
            let rawBytes = [];
            if (getObj && getObj.ioLink && getObj.ioLink.value !== undefined) {
                let v = getObj.ioLink.value;
                if (Array.isArray(v)) rawBytes = v;
                else if (typeof v === 'string') rawBytes = v.trim().split(/\s+/).map(x => parseInt(x, 10));
                else if (typeof v === 'number') rawBytes = [v];
            } else if (Array.isArray(d.value)) {
                rawBytes = d.value;
            }
            let iodd = global.get('port_iodd_' + pdPort);
            state.ports[pdIdx].pdValues = unpackProcessData(rawBytes, iodd);
        }
    }
}

flow.set('nass_core_state', state);
global.set('nass_core_state', state);
return { topic: 'state_update', payload: state };

let masterIp = global.get('master_ip') || flow.get('master_ip') || '192.168.23.100';
if (msg.topic === 'set_master_ip') {
    let newIp = String(msg.payload || '').trim();
    if (newIp) {
        global.set('master_ip', newIp);
        flow.set('master_ip', newIp);
        node.status({ fill: 'green', shape: 'dot', text: 'Master IP: ' + newIp });
    }
    return null;
}
let cmd = msg.payload;
if (!cmd || !cmd.port) return null;
let alias = `master1port${cmd.port}`;
if (msg.topic === 'set_mode') {
    global.set('port_mode_' + cmd.port, cmd.mode);
    let nassState = global.get('nass_core_state') || {};
    if (nassState.ports && nassState.ports[cmd.port - 1]) {
        nassState.ports[cmd.port - 1].mode = cmd.mode;
        global.set('nass_core_state', nassState);
    }
    let payload = { deviceAlias: alias };
    if (cmd.mode === 'DIGITAL_INPUT') payload.iqConfiguration = 'DIGITAL_INPUT';
    else if (cmd.mode === 'DIGITAL_OUTPUT') payload.iqConfiguration = 'NOT_SUPPORTED';
    payload.mode = cmd.mode;
    return { url: `http://${masterIp}/iolink/v1/masters/1/ports/${cmd.port}/configuration`, method: 'POST', payload: payload };
}
if (msg.topic === 'set_do') {
    let isHigh = cmd.state === true;
    global.set('port_do_' + cmd.port, isHigh);
    let nassState = global.get('nass_core_state') || {};
    if (nassState.ports && nassState.ports[cmd.port - 1]) {
        nassState.ports[cmd.port - 1].doState = isHigh;
        global.set('nass_core_state', nassState);
    }
    return { url: `http://${masterIp}/iolink/v1/devices/${alias}/processdata/value`, method: 'POST', payload: { cqValue: isHigh } };
}
return null;

let masterIp = global.get('master_ip') || flow.get('master_ip') || '192.168.23.100';
let msgs = [];
for (let i = 1; i <= 4; i++) {
    let alias = `master1port${i}`;
    msgs.push({ 
        url: `http://${masterIp}/iolink/v1/devices/${alias}/identification`,
        portId: i,
        reqType: 'dev_ident'
    });
    msgs.push({ 
        url: `http://${masterIp}/iolink/v1/devices/${alias}/parameters/21/value`,
        portId: i,
        reqType: 'dev_sn'
    });
}
return [msgs];

let state = msg.payload;
if (!state || !state.ports) return null;
let ports = Array.isArray(state.ports) ? state.ports : Object.values(state.ports);
let csvEnabled = flow.get('csv_logging_enabled') || false;
let timestamp = new Date().toISOString();
let csvLines = [];

function parseNum(raw) {
    if (typeof raw === 'number') return isNaN(raw) ? 0 : raw;
    if (typeof raw === 'boolean') return raw ? 1 : 0;
    if (!raw) return 0;
    let s = String(raw).trim().toUpperCase();
    if (s.includes('HIGH') || s.startsWith('ON') || s === 'TRUE' || s.includes('24V')) return 1;
    if (s.includes('LOW') || s.startsWith('OFF') || s === 'FALSE' || s.includes('0V')) return 0;
    let n = parseFloat(s.replace(/[^0-9.-]/g, ''));
    return isNaN(n) ? 0 : n;
}

let allPortsPd = {};

ports.forEach((pData, index) => {
    if (!pData) return;
    let portId = pData.id || (index + 1);
    let pdVal = 0;
    let rawPd = pData.pdValues || pData.processData || pData.pd || pData.value;
    allPortsPd[portId] = pData.pdValues || {};

    if (rawPd !== undefined && rawPd !== null) {
        if (typeof rawPd === 'number' || typeof rawPd === 'boolean' || typeof rawPd === 'string') {
            pdVal = parseNum(rawPd);
        } else if (typeof rawPd === 'object') {
            for (let k in rawPd) {
                let item = rawPd[k];
                if (item && typeof item === 'object' && item.val !== undefined) {
                    pdVal = parseNum(item.val);
                    break;
                }
            }
        }
    }
    flow.set('port_pd_' + portId, pdVal);
    global.set('port_pd_' + portId, pdVal);
    if (csvEnabled) csvLines.push(`${timestamp};Port_${portId};PD;${pdVal}`);
});

global.set('live_ports_pd', allPortsPd);

let streamMsg = {
    topic: 'diag_poll_data',
    payload: {
        timestamp: Date.now(),
        allPortsPd: allPortsPd,
        coreState: state
    }
};

let csvPayload = csvEnabled && csvLines.length > 0 ? csvLines.join('\n') + '\n' : null;
return [streamMsg, csvPayload];

let masterIp = global.get('master_ip') || flow.get('master_ip') || '192.168.23.100';
if (msg.topic === 'get_ports_data') {
    let ports = [];
    let nassState = global.get('nass_core_state') || {};
    let nassPorts = nassState.ports || [];
    for (let i = 1; i <= 4; i++) {
        let pState = nassPorts[i - 1] || {};
        let pMode = global.get('port_mode_' + i) || pState.mode || 'IOLINK_AUTOSTART';
        let doState = (pState.doState !== undefined) ? pState.doState : false;
        let diState = (pState.diState !== undefined) ? pState.diState : false;
        let iodd = global.get('port_iodd_' + i);

        if (pMode === 'DIGITAL_INPUT') {
            ports.push({
                id: i,
                active: true,
                mode: 'DIGITAL_INPUT',
                deviceName: 'DIGITÁLIS BEMENET (DI)',
                diState: diState,
                doState: false
            });
            continue;
        }
        if (pMode === 'DIGITAL_OUTPUT') {
            ports.push({
                id: i,
                active: true,
                mode: 'DIGITAL_OUTPUT',
                deviceName: 'DIGITÁLIS KIMENET (DO)',
                diState: false,
                doState: doState
            });
            continue;
        }
        if (pMode === 'DEACTIVATED') {
            ports.push({
                id: i,
                active: false,
                mode: 'DEACTIVATED',
                deviceName: 'INAKTÍV',
                diState: false,
                doState: false
            });
            continue;
        }

        if (!iodd || !iodd.valid) {
            ports.push({
                id: i,
                active: true,
                mode: pMode,
                deviceName: pState.device || 'Nincs IODD',
                diState: false,
                doState: false,
                pdValues: pState.pdValues || {}
            });
            continue;
        }

        let scaledVar = (iodd.variables && iodd.variables.length > 0) ? (iodd.variables.find(v => v.scale && v.scale.gradient && v.scale.gradient !== 1) || iodd.variables[0]) : null;
        let scale = scaledVar ? (scaledVar.scale || { gradient: 1, offset: 0 }) : { gradient: 1, offset: 0 };
        let unit = scaledVar ? (scaledVar.unit || iodd.unit || '') : (iodd.unit || '');
        ports.push({
            id: i,
            active: true,
            mode: pMode,
            doState: doState,
            diState: diState,
            vendorId: parseInt(iodd.vendorId, 10) || 0,
            bitLenOut: iodd.bitLengthOut || 0,
            deviceName: iodd.deviceName,
            vars: iodd.variables || [],
            iodd: {
                bitLengthIn: iodd.bitLengthIn || 16,
                bitLengthOut: iodd.bitLengthOut || 0,
                unit: unit,
                scale: scale,
                deviceIdHex: iodd.deviceIdHex || '---',
                processDataInItems: iodd.processDataInItems || [],
                processDataOutItems: iodd.processDataOutItems || []
            }
        });
    }
    return [[{ topic: 'init_data', payload: ports }], null];
}
let safeAlias = `master1port${msg.portId}`;
if (msg.topic === 'fetch_pd') {
    let mode = global.get('port_mode_' + msg.portId) || 'IOLINK_AUTOSTART';
    if (mode === 'DEACTIVATED') return [null, null];
    return [null, { portId: msg.portId, action: 'pd_fetch', url: `http://${masterIp}/iolink/v1/devices/${safeAlias}/processdata/value?format=byteArray`, method: 'GET', timeout: 2500 }];
}
if (msg.topic === 'isdu_cmd') {
    let isduUrl = (msg.subindex !== undefined && msg.subindex !== null && Number(msg.subindex) > 0)
        ? `http://${masterIp}/iolink/v1/devices/${safeAlias}/parameters/${msg.index}/subindices/${msg.subindex}/value?format=byteArray`
        : `http://${masterIp}/iolink/v1/devices/${safeAlias}/parameters/${msg.index}/value?format=byteArray`;
    return [null, { portId: msg.portId, action: msg.action, url: isduUrl, method: msg.action === 'write' ? 'POST' : 'GET', payload: msg.action === 'write' ? { value: msg.value } : {}, timeout: 3500 }];
}
if (msg.topic === 'pd_cmd') return [null, { portId: msg.portId, action: 'pd_write', url: `http://${masterIp}/iolink/v1/devices/${safeAlias}/processdata/value`, method: 'POST', payload: { ioLink: { valid: true, value: msg.value } }, timeout: 2500 }];
if (msg.topic === 'set_mode') {
    global.set('port_mode_' + msg.portId, msg.mode);
    let nassState = global.get('nass_core_state') || {};
    if (nassState.ports && nassState.ports[msg.portId - 1]) {
        nassState.ports[msg.portId - 1].mode = msg.mode;
        if (msg.mode === 'DIGITAL_OUTPUT') nassState.ports[msg.portId - 1].status = 'DO_AKTÍV';
        else if (msg.mode === 'DIGITAL_INPUT') nassState.ports[msg.portId - 1].status = 'DI_AKTÍV';
        else if (msg.mode === 'DEACTIVATED') nassState.ports[msg.portId - 1].status = 'INAKTÍV';
        else nassState.ports[msg.portId - 1].status = 'ONLINE';
        global.set('nass_core_state', nassState);
    }
    let payload = { deviceAlias: safeAlias, mode: msg.mode };
    if (msg.mode === 'DIGITAL_INPUT') payload.iqConfiguration = 'DIGITAL_INPUT';
    else if (msg.mode === 'DIGITAL_OUTPUT') payload.iqConfiguration = 'NOT_SUPPORTED';
    return [null, { portId: msg.portId, action: 'set_mode', url: `http://${masterIp}/iolink/v1/masters/1/ports/${msg.portId}/configuration`, method: 'POST', payload: payload, timeout: 3000 }];
}
if (msg.topic === 'set_do') {
    let isHigh = (msg.state === true);
    let nassState = global.get('nass_core_state') || {};
    if (nassState.ports && nassState.ports[msg.portId - 1]) {
        nassState.ports[msg.portId - 1].doState = isHigh;
        global.set('nass_core_state', nassState);
    }
    return [null, { portId: msg.portId, action: 'do_write', url: `http://${masterIp}/iolink/v1/devices/${safeAlias}/processdata/value`, method: 'POST', payload: { cqValue: isHigh }, timeout: 2500 }];
}
return [null, null];

function unpackProcessData(bytes, iodd) {
    let results = {};
    if (!Array.isArray(bytes) || bytes.length === 0 || !iodd || !iodd.valid) return results;
    let totalBits = 0n;
    bytes.forEach(b => { totalBits = (totalBits << 8n) | BigInt(b); });
    if (iodd.processDataInItems && iodd.processDataInItems.length > 0) {
        iodd.processDataInItems.forEach(item => {
            let bitLen = BigInt(item.bitLen || 16);
            let bitOffset = BigInt(item.bitOffset || 0);
            let mask = (1n << bitLen) - 1n;
