    let srcPortData = (coreState && coreState.ports && coreState.ports[srcPortId - 1]) ? coreState.ports[srcPortId - 1] : null;
    let rawVal = 0;

    if (src.sourceType === "ISDU") {
        let isduIdx = src.isduIndex || parseInt(String(src.channelKey || "").replace(/[^0-9]/g, "")) || 0;
        let isduSub = src.isduSubindex || 0;
        let globalIsdu = isduSub > 0 ? global.get(`port_${srcPortId}_isdu_${isduIdx}_${isduSub}`) : global.get(`port_${srcPortId}_isdu_${isduIdx}`);
        if (globalIsdu === undefined) {
