    return { topic: "plc_eval_tick" };
}

if (topic === "plc_delete_rule") {
    let rList = global.get("plc_rules") || [];
    if (ruleId) {
        rList = rList.filter(r => r.id !== ruleId);
    }
    if (rules && Array.isArray(rules)) {
        rList = rules;
    }
    global.set("plc_rules", rList);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_toggle_rule") {
    let rList = global.get("plc_rules") || [];
    let r = rList.find(x => x.id === ruleId);
    if (r) r.enabled = !r.enabled;
    global.set("plc_rules", rList);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_update_threshold") {
    let rList = global.get("plc_rules") || [];
    let r = rList.find(x => x.id === ruleId);
    if (r && r.source && threshold !== undefined) {
        r.source.threshold = Number(threshold);
    }
    global.set("plc_rules", rList);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_reset_defaults") {
    global.set("plc_rules", null);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_clear_all" || topic === "plc_clear_rules") {
    global.set("plc_rules", []);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_clear_logs") {
    global.set("plc_logs", []);
    return { topic: "plc_eval_tick" };
}

if (topic === "plc_eval_tick") {
    return msg;
}

return null;

let coreState = global.get("nass_core_state");
let allPortsPd = {};
for (let i = 1; i <= 4; i++) {
    let pData = (coreState && coreState.ports && coreState.ports[i-1]) ? coreState.ports[i-1] : null;
    allPortsPd[i] = pData?.pdValues || {};
}
return { topic: "diag_poll_data", payload: { timestamp: Date.now(), allPortsPd: allPortsPd } };
